                            }
                        } else {
                            alt (loomv_smallpay_3w.status == "PAID") {
                                return "Refund payment completed."
                            } else {
                                human_prompt "Payment was not confirmed. Send this request to the human review queue." -> loomv_smallunconfirmed_3p
                                halt "Payment was not confirmed; human review is required."
