                halt "Order identifier or amount is unverifiable; human review is required."
            }
        } else {
            human_prompt "The order text is ambiguous or unverifiable. Send this request to the human review queue; do not calculate or pay it." -> loomv_review_1c
            halt "Order is ambiguous or unverifiable; human review is required."
