budget { tokens: 60000  calls: 20 }

tool Calculator { use: calculator }

tool PaymentLookup {
    use: http
    base_url: env.PAYMENT_API_URL
    auth_header: "Authorization"
    auth_value: env.PAYMENT_API_KEY
    allow_paths: "/v1/refunds"
    methods: "GET"
}

tool PaymentApi {
    use: http
    base_url: env.PAYMENT_API_URL
    auth_header: "Authorization"
    auth_value: env.PAYMENT_API_KEY
    allow_paths: "/v1/refunds"
    methods: "POST"
}

tool CustomerMail {
    use: email
    host: env.SMTP_HOST
    username: env.SMTP_USER
    password: env.SMTP_PASSWORD
    from: env.SMTP_FROM
    to: env.CUSTOMER_EMAIL
    security: "starttls"
}

agent RefundCalculator {
    model: "gpt-6-luna"
    prompt: "refundcalculator"
    temperature: 0.2
    tools: [Calculator]
    max_iterations: 4
    guard { pii: mask }
    output_schema: {
        order_id: string,
        amount: number,
        currency: string,
        over_threshold: enum["yes", "no"]
    }
}

agent RefundPayer {
    model: "gpt-6-luna"
    prompt: "refundpayer"
    temperature: 0.2
    tools: [PaymentLookup, PaymentApi]
    approve: [PaymentApi]
    max_iterations: 4
    guard { pii: mask }
    output_schema: {
        status: enum["PAID", "DUPLICATE", "FAILED"]
    }
}

agent CustomerNotifier {
    model: "gpt-6-luna"
    prompt: "customernotifier"
    temperature: 0.2
    tools: [CustomerMail]
    approve: [CustomerMail]
    max_iterations: 3
